123			queuedAt: base.Add(3 * time.Second),
124			status:   StatusQueued,
125		})
126		// 作业 4：与重复记录无关的排队作业，重开后应照常完成。
127		writeSyntheticRecord(t, dir, &storedJob{
128			id: 4, submitter: "b", requestID: "indep",
129			values:   []int64{1, 2, 3},
130			queuedAt: base.Add(4 * time.Second),
131			status:   StatusQueued,
132		})
133	
134		s, err := Open(dir)
135		if err != nil {
136			t.Fatal(err)
137		}
138		defer s.Close()
139	
140		assertDuplicateDependencyFailure(t, s, 2, 1)
141	
142		// 被重复引用的上游仍保留自己的成功结果。
143		gUp, _ := s.Get(1)
144		if gUp.Status != StatusSucceeded || gUp.Archive == nil || gUp.Archive.Sum != 3 {
145			t.Fatalf("duplicated-but-valid upstream must keep its result: status=%s archive=%v",
146				gUp.Status, gUp.Archive)
147		}
148	
149		// 下游按既有依赖失败规则处理：直接上游是作业 2，根因也是作业 2
150		//（重复记录自身 BlockerID 为 0，根因不另指他人）。
151		child := waitStatus(t, s, 3, StatusFailed)
152		if child.BlockerID != 2 {
153			t.Fatalf("child blocker=%d want root 2 (the duplicate record itself)", child.BlockerID)
154		}
155		if !strings.Contains(child.FailureReason, "直接上游作业 2") ||
156			!strings.Contains(child.FailureReason, "依赖列表重复") {
157			t.Fatalf("child must name direct upstream 2 and carry its duplicate reason: %q",
158				child.FailureReason)
159		}
160		if child.Archive != nil || !child.StartedAt.IsZero() {
161			t.Fatalf("blocked child must never compute: started=%s archive=%v",
162				child.StartedAt, child.Archive)
163		}
164	
165		// 无关记录继续正常查询与调度。
166		indep := waitStatus(t, s, 4, StatusSucceeded)
167		if indep.Archive.Sum != 6 || indep.Archive.SumOfSquares != 14 {
168			t.Fatalf("unrelated job result=%d,%d want 6,14", indep.Archive.Sum, indep.Archive.SumOfSquares)
169		}
170	
171		// 再次重开：失败结果已保存在目录中，状态、原因与根因保持稳定，归档仍可用。
172		if err := s.Close(); err != nil {
173			t.Fatal(err)
174		}
175		s3, err := Open(dir)
176		if err != nil {
177			t.Fatal(err)
178		}
179		defer s3.Close()
180		assertDuplicateDependencyFailure(t, s3, 2, 1)
181		gChild2 := waitStatus(t, s3, 3, StatusFailed)
182		if gChild2.BlockerID != 2 {
183			t.Fatalf("after second reopen child blocker=%d want 2", gChild2.BlockerID)
184		}
185	}
186	
187	// 重复引用不要求相邻：[a,b,a] 中作业 a 隔着 b 再次出现，失败原因指出首次
188	// 再次出现的 a；被引用的两个上游都保持成功。
189	func TestReopenRejectsNonAdjacentDuplicateDependency(t *testing.T) {
190		dir := t.TempDir()
191		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
192		// 作业 1 总和 3，作业 2 总和 5。
193		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
194		syntheticSucceededRecord(t, dir, 2, []int64{5}, []int64{5}, nil, base)
195		// 作业 3：依赖 [1,2,1]，实际输入 [10,3,5,3]（sum=21, sq=143，全套自洽）。
196		dup := syntheticSucceededRecord(t, dir, 3,
197			[]int64{10}, []int64{10, 3, 5, 3}, []uint64{1, 2, 1}, base)
198		if dup.archive.Sum != 21 || dup.archive.SumOfSquares != 143 {
199			t.Fatalf("dup result=%d,%d want 21,143", dup.archive.Sum, dup.archive.SumOfSquares)
200		}
201	
202		s, err := Open(dir)
203		if err != nil {
204			t.Fatal(err)
205		}
206		defer s.Close()
207	
208		assertDuplicateDependencyFailure(t, s, 3, 1)
209		for _, id := range []uint64{1, 2} {
210			g, _ := s.Get(id)
211			if g.Status != StatusSucceeded || g.Archive == nil {
212				t.Fatalf("valid upstream %d must stay succeeded: %s", id, g.Status)
213			}
214		}
215	}
216	
217	// 排队记录的依赖列表重复时，重开后直接失败，不能开始计算（无开始时间、
218	// 无归档与实际输入）；等待它的下游随之失败，根因为该重复记录自身。
219	func TestReopenQueuedDuplicateDependencyFailsWithoutComputing(t *testing.T) {
220		dir := t.TempDir()
221		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
222		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
223		// 作业 2：排队，依赖列表重复 [1,1]。
224		writeSyntheticRecord(t, dir, &storedJob{
225			id: 2, submitter: "a", requestID: "dup",
226			values: []int64{10}, dependencies: []uint64{1, 1},
227			queuedAt: base.Add(2 * time.Second),
228			status:   StatusQueued,
229		})
230		// 作业 3：排队等待作业 2。
231		writeSyntheticRecord(t, dir, &storedJob{
232			id: 3, submitter: "a", requestID: "child",
233			values: []int64{20}, dependencies: []uint64{2},
234			queuedAt: base.Add(3 * time.Second),
235			status:   StatusQueued,
236		})
237	
238		s, err := Open(dir)
239		if err != nil {
240			t.Fatal(err)
241		}
242		defer s.Close()
243	
244		assertDuplicateDependencyFailure(t, s, 2, 1)
245		g2, _ := s.Get(2)
246		if !g2.StartedAt.IsZero() {
247			t.Fatalf("duplicated queued job must never start computing, started=%s", g2.StartedAt)
248		}
249	
250		child := waitStatus(t, s, 3, StatusFailed)
251		if child.BlockerID != 2 || !strings.Contains(child.FailureReason, "直接上游作业 2") {
252			t.Fatalf("child blocker=%d reason=%q want root 2 named as direct upstream",
253				child.BlockerID, child.FailureReason)
254		}
255	}
256	
257	// 唯一性按作业号判断，而非按上游总和：两个不同上游都得到 3，各引用一次时
258	// 实际输入同样是 [10,3,3]，仍属合法记录，重开后保持成功，次序与结果不变。
259	func TestReopenEqualSumDistinctUpstreamsRemainLegal(t *testing.T) {
260		dir := t.TempDir()
261		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
262		// 两个不同作业号，总和都为 3。
263		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
264		syntheticSucceededRecord(t, dir, 2, []int64{0, 3}, []int64{0, 3}, nil, base)
265		// 作业 3：依赖 [1,2]（作业号不同），追加 [3,3] 合法。
266		down := syntheticSucceededRecord(t, dir, 3,
267			[]int64{10}, []int64{10, 3, 3}, []uint64{1, 2}, base)
268	
269		s, err := Open(dir)
270		if err != nil {
271			t.Fatal(err)
272		}
273		defer s.Close()
274	
275		g, err := s.Get(3)
276		if err != nil {
277			t.Fatal(err)
278		}
279		if g.Status != StatusSucceeded || g.Archive == nil {
280			t.Fatalf("distinct upstreams with equal sums must stay legal: %s", g.Status)
281		}
282		if g.Archive.Sum != 16 || g.Archive.SumOfSquares != 118 ||
283			g.Archive.Checksum != down.archive.Checksum {
284			t.Fatalf("legal multi-dependency result changed: %+v", g.Archive)
285		}
286		if len(g.Dependencies) != 2 || g.Dependencies[0] != 1 || g.Dependencies[1] != 2 {
287			t.Fatalf("dependency order changed: %v", g.Dependencies)
288		}
289	}
290	
291	// 已经失败或取消的记录即使保存了重复依赖列表，也保留既有终态、原因与根因，
292	// 不被恢复阶段的唯一性检查改写。
293	func TestReopenDuplicateDependencyKeepsExistingTerminalRecords(t *testing.T) {
294		dir := t.TempDir()
295		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
296		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
297		failedAt := base.Add(2 * time.Second)
298		writeSyntheticRecord(t, dir, &storedJob{
299			id: 2, submitter: "a", requestID: "f",
300			values: []int64{10}, dependencies: []uint64{1, 1},
301			queuedAt: failedAt, finishedAt: failedAt,
302			status:        StatusFailed,
303			failureReason: "既有的失败原因",
304			blockerID:     9,
305		})
306		writeSyntheticRecord(t, dir, &storedJob{
307			id: 3, submitter: "a", requestID: "c",
308			values: []int64{11}, dependencies: []uint64{1, 1},
309			queuedAt: base.Add(3 * time.Second), finishedAt: base.Add(4 * time.Second),
310			status: StatusCanceled,
311		})
312	
313		s, err := Open(dir)
314		if err != nil {
315			t.Fatal(err)
316		}
317		defer s.Close()
318	
319		gf, _ := s.Get(2)
320		if gf.Status != StatusFailed || gf.BlockerID != 9 || gf.FailureReason != "既有的失败原因" {
321			t.Fatalf("existing failed record must be preserved: status=%s blocker=%d reason=%q",
322				gf.Status, gf.BlockerID, gf.FailureReason)
323		}
324		gc, _ := s.Get(3)
325		if gc.Status != StatusCanceled || gc.BlockerID != 0 || gc.FailureReason != "" {
326			t.Fatalf("existing canceled record must be preserved: status=%s blocker=%d reason=%q",
327				gc.Status, gc.BlockerID, gc.FailureReason)
328		}
329	}
