			time.Sleep(time.Millisecond)
		}
		return 0, 0, "aborted", false
	}
}

// 时钟回拨后重新打开归档：调度顺序、按提交人列举的顺序都必须仍是
// 接受先后（作业号顺序），记录上的提交时间只用于范围过滤。
func TestReopenPreservesAcceptanceOrder(t *testing.T) {
	dir := t.TempDir()
